float ageLine(float d, float w) { return 1.0 - smoothstep(0.0, w, abs(d)); }
float ageSeg(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}
`;

