  float zone = max(max(smoothstep(0.8, 1.1, q.y), smoothstep(1.0, 1.25, ax) * smoothstep(-0.2, 0.2, q.y)), smoothstep(-0.8, -1.2, q.z) * smoothstep(-1.0, -0.6, q.y));
  float hair = zone * smoothstep(0.85, 0.55, lum / skinLum);
