// Screenshot the XR page with files served from disk by Playwright itself (no server process).
// Usage: node shot.mjs <repoDir> <path?query> <out.png> [js-to-eval] [wait-ms]
import { chromium } from "playwright";
import { readFile } from "node:fs/promises";
import path from "node:path";

const [, , repo, page, out, js = "", wait = "4000"] = process.argv;
const TYPES = { ".html": "text/html", ".js": "text/javascript", ".mjs": "text/javascript", ".css": "text/css", ".json": "application/json", ".glb": "model/gltf-binary", ".wav": "audio/wav" };
const b = await chromium.launch({ args: ["--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "--autoplay-policy=no-user-gesture-required"] });
const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
const errs = [];
p.on("console", (m) => (m.type() === "error" || m.type() === "warning") && errs.push(`${m.type()}: ${m.text()}`));
p.on("pageerror", (e) => errs.push(String(e)));
await p.route("http://uncle.local/**", async (route) => {
  const url = new URL(route.request().url());
  let rel = decodeURIComponent(url.pathname);
  if (rel.endsWith("/")) rel += "index.html";
  const file = path.join(repo, rel);
  try {
    await route.fulfill({ status: 200, body: await readFile(file), contentType: TYPES[path.extname(file)] || "application/octet-stream" });
  } catch {
    await route.fulfill({ status: 404, body: "not found" });
  }
});
await p.goto(`http://uncle.local${page}`);
await p.waitForFunction(() => !document.getElementById("start").disabled, null, { timeout: 60000 });
await p.waitForTimeout(1500);
if (js) console.log("eval:", JSON.stringify(await p.evaluate(js)));
await p.waitForTimeout(+wait);
if (process.env.AFTER) console.log("after:", JSON.stringify(await p.evaluate(process.env.AFTER)));
await p.screenshot({ path: out });
console.log("errors:", errs.length ? errs : "none");
await b.close();

