python - <<'EOF'
p='xr/age.js'; s=open(p,encoding='utf-8').read()
old_hair=s[s.index('  // Hair: in the hair zone'):s.index('  // Skin: a little less colour')]
new_hair='''  // Hair: in the hair zone and darker than the skin (the crown counts as hair whatever its
  // colour, so light patches in the scan don't stay brown). Grey comes in strand by strand and
  // keeps the texture's own light and dark so it still reads as hair.
  float zone = max(max(ageSS(0.45, 0.75, q.y), ageSS(1.0, 1.25, ax) * ageSS(-0.2, 0.2, q.y)), ageSS(-0.8, -1.2, q.z) * ageSS(-1.0, -0.6, q.y));
  float hair = zone * max(ageSS(0.8, 0.5, lum / skinLum), ageSS(1.1, 1.4, q.y));
  float strand = ageNoise(vec2(q.x * 180.0 + q.z * 60.0, q.y * 18.0));
  float greyShare = ageSS(0.15, 0.9, uAge);
  float grey = hair * ageSS(strand - 0.15, strand + 0.15, greyShare);
  float detail = clamp(lum / (skinLum * 0.45), 0.0, 1.6);
  vec3 greyCol = vec3(0.30, 0.295, 0.285) * (0.55 + 0.55 * detail) * (0.85 + 0.3 * strand);
  c = mix(c, greyCol, grey * 0.92);

'''
s=s.replace(old_hair,new_hair)
s=s.replace('c = mix(c, vec3(lum), 0.18 * uAge * skin);','c = mix(c, vec3(lum), 0.25 * uAge * skin);')
s=s.replace('c *= mix(vec3(1.0), vec3(1.0, 0.96, 0.88), uAge * skin);','c *= mix(vec3(1.0), vec3(0.97, 0.92, 0.84), uAge * skin);')
s=s.replace('c *= 1.0 - clamp(lines, 0.0, 1.0) * 0.22 * ageSS(0.2, 1.0, uAge) * face;','c *= 1.0 - clamp(lines, 0.0, 1.0) * 0.4 * ageSS(0.2, 1.0, uAge) * face;')
s=s.replace('c *= 1.0 - spots * 0.22 * uAge','c *= 1.0 - spots * 0.3 * uAge')
open(p,'w',encoding='utf-8',newline='\n').write(s)
EOF
grep -n "export function hairZone" -A4 xr/age.js | head -3

